-- Enable (default on in PG 11+)
SET max_parallel_workers_per_gather = 4;

-- Cost thresholds
SET parallel_setup_cost = 1000;      -- default 1000
SET parallel_tuple_cost = 0.1;       -- default 0.1

-- Force parallel for testing
SET force_parallel_mode = on;

-- Check if query uses parallel
EXPLAIN ANALYZE SELECT count(*) FROM large_table;

-- Huge table, naturally ordered by time
CREATE INDEX idx_events_ts_brin ON events USING BRIN (created_at);

-- Pages per range (default 128)
CREATE INDEX idx_events_ts_brin32 ON events USING BRIN (created_at) WITH (pages_per_range = 32);

-- Size comparison
-- B-tree: ~1.2 GB  |  BRIN: ~40 MB (for 1B rows)

-- Case-insensitive unique constraint
CREATE UNIQUE INDEX idx_users_email_lower ON users (LOWER(email));

-- Custom collation (PostgreSQL 12+)
CREATE COLLATION case_insensitive (provider = icu, locale = 'und-u-ks-level2', deterministic = false);
CREATE TABLE users (email TEXT COLLATE case_insensitive UNIQUE);

-- JSONB path index
CREATE INDEX idx_data_tags ON events USING GIN ((data->'tags'));
-- Query: data->'tags' @> '["urgent"]'

